           "skb_linearize_cow","skb_linearize","pskb_trim_rcsum","pskb_trim",
           "pskb_carve","skb_copy_expand_head"]

helper_re = re.compile(r"\b(" + "|".join(helpers) + r")\s*\(")

# pointer-deriving patterns (right-hand side)
derive_re = re.compile(r"=\s*(?:\(?\s*[\w\s\*]*\*\s*\)?\s*)?(?:skb->data|.*->data\b|skb_header_pointer|skb_network_header|skb_transport_header|skb_mac_header|skb_payload_type|__skb_header_pointer|skb_reset|->head\b)")
derive_hint = re.compile(r"=\s*(.*->data\b|.*skb_header_pointer\s*\(|.*skb_network_header\s*\(|.*skb_transport_header\s*\(|.*skb_mac_header\s*\(|.*->head\b)")

def functions(lines):
    # crude: function starts at line whose first non-space char is at col 0 and ends with '{'
    start=None; name=None
    for i,l in enumerate(lines):
        if l and not l[0].isspace() and not l.startswith(("#","}","/","*"," ","\t")):
            m = re.match(r"[\w\*\s]+\**(\w+)\s*\(", l)
            if l.rstrip().endswith("{") and m:
                if start is not None:
                    yield (start,i,name)
                start=i; name=m.group(1)
            elif l.rstrip().endswith(";") and start is None:
                pass
        if l.startswith("}") and start is not None:
            yield (start,i+1,name)
            start=None; name=None
    if start is not None:
        yield (start,len(lines),name)

results=[]
