            for idx,l in before:
                dm = re.match(r"\s*(?:const\s+)?(?:struct\s+)?[\w\*]+\s*\**\s*(\w+)\s*=\s*(.*);", l)
                if dm:
                    rhs=dm.group(2)
                    if derive_hint.search(rhs):
                        ptrvars[dm.group(1)]=(idx+1,l.strip())
            if not ptrvars: continue
            # check usage after call
            used=[]
