                    if re.search(r"\b"+re.escape(v)+r"\b\s*(->|\[|\.|;|\)|\+|\-)", l) or re.search(r"\*\s*"+re.escape(v)+r"\b", l) or re.search(r"\(\s*"+re.escape(v)+r"\s*\)", l):
                        used.append((v,idx+1,l.strip()))
                        break
            if used:
                results.append((path,call_lineno+1,name,m.group(1),[(ptrvars[v][0],ptrvars[v][1]) for v in dict(used)],[ (u[1],u[2],u[0]) for u in used]))

for r in results:
    print("### %s:%d func=%s helper=%s" % (r[0],r[1],r[2],r[3]))
    print("   save:", r[4])
    print("   use :", r[5])
