    out=[]; stack=[]
    start=None; name=None
    for i,l in enumerate(lines):
        if l and not l[0].isspace() and not l.startswith(("#","/","*")) and "(" in l:
            m = re.match(r"[\w\*\s]+\**(\w+)\s*\(", l)
            if m and not re.match(r"^\s*(if|for|while|switch|return|else)\b", l):
