import re, sys

helpers = ["pskb_expand_head","skb_realloc_headroom","skb_cow_head","skb_cow",
           "skb_linearize_cow","skb_linearize","pskb_trim_rcsum","pskb_trim",
           "pskb_carve","skb_copy_expand_head"]
