for path in sys.argv[1:]:
    try: lines=open(path,errors="replace").read().split("\n")
    except: continue
    # functions: line at col 0 with '(' and ending '{' possibly on following lines
    fnstarts=[]
    for i,l in enumerate(lines):
        if l and not l[0].isspace() and not l.startswith(("#","/","*","}")) and "(" in l:
            if re.match(r"^\s*(if|for|while|switch|return|else|EXPORT|MODULE|DEFINE)\b", l): continue
            # look ahead for '{' before ';' at col0
            j=i
            while j<i+8 and j<len(lines):
                if lines[j].rstrip().endswith("{"): fnstarts.append(i); break
                if lines[j].rstrip().endswith(";") and j>i: break
                if lines[j].startswith("}"): break
                j+=1
    for si,fs in enumerate(fnstarts):
        fe = fnstarts[si+1] if si+1<len(fnstarts) else len(lines)
        # actual end: next line starting with '}' at col0 after fs
        for k in range(fs+1,len(lines)):
            if lines[k].startswith("}"): fe=k+1; break
        body=lines[fs:fe]
        for i,l in enumerate(body):
            m=helper_re.search(l)
            if not m or l.lstrip().startswith(("*","//","/*")): continue
            before=body[:i]; after=body[i+1:]
            ptrvars={}
            for j,bl in enumerate(before):
                dm = re.match(r"\s*(?:const\s+)?(?:struct\s+)?[\w\*]+\s*\**\s*(\w+)\s*=\s*(.+);", bl)
                if dm and derive_hint.search(dm.group(2)):
                    ptrvars[dm.group(1)]=(fs+j+1,bl.strip())
            if not ptrvars: continue
            hits=[]
            for v in ptrvars:
                for j,al in enumerate(after):
                    if re.search(r"\b"+re.escape(v)+r"\b\s*(->|\[|\.)", al) or re.search(r"\*\s*"+re.escape(v)+r"\b", al):
                        hits.append((v,fs+1+j+1,al.strip())); break
            if hits:
